<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Pembiayaan,TahunAnggaran}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class PembiayaanController extends Controller { public function index():View{return view('admin.pembiayaan.index',['items'=>Pembiayaan::with('tahunAnggaran')->orderByDesc('tahun_anggaran_id')->orderBy('urutan')->paginate(12)]);} public function create():View{return view('admin.pembiayaan.form',['years'=>TahunAnggaran::orderByDesc('tahun')->get()]);} public function edit(Pembiayaan $pembiayaan):View{return view('admin.pembiayaan.form',['item'=>$pembiayaan,'years'=>TahunAnggaran::orderByDesc('tahun')->get()]);} public function store(Request $r):RedirectResponse{Pembiayaan::create($this->valid($r));return to_route('admin.pembiayaan.index')->with('success','Pembiayaan ditambahkan.');} public function update(Request $r,Pembiayaan $pembiayaan):RedirectResponse{$pembiayaan->update($this->valid($r));return to_route('admin.pembiayaan.index')->with('success','Pembiayaan diperbarui.');} public function destroy(Pembiayaan $pembiayaan):RedirectResponse{$pembiayaan->delete();return back()->with('success','Pembiayaan dihapus.');} public function publication(Pembiayaan $pembiayaan):RedirectResponse{$pembiayaan->update(['status_publikasi'=>$pembiayaan->status_publikasi==='dipublikasikan'?'draft':'dipublikasikan']);return back()->with('success','Status publikasi diperbarui.');} private function valid(Request $r):array{return $r->validate(['tahun_anggaran_id'=>'required|exists:tahun_anggaran,id','jenis'=>'required|in:penerimaan,pengeluaran','kode'=>'required|max:50','uraian'=>'required|max:255','anggaran'=>'required|numeric|min:0','urutan'=>'nullable|integer|min:0','status_publikasi'=>'required|in:draft,dipublikasikan']);}}
